    key_array = extract_array(key, extract_numpy=True)

    if isinstance(key_array, slice):
        slobj = self.index._convert_slice_indexer(key_array, kind="getitem")
        return self._slice(slobj)
    elif isinstance(key_array, ABCDataFrame):
        raise TypeError(
            "Indexing a Series with DataFrame is not "
            "supported, use the appropriate DataFrame column"
        )
    elif isinstance(key_array, tuple):
        return self._get_values_tuple(key_array)

    if not is_list_like(key_array):
